lessons.solution_code:
def first_index(items, pred):
    for i, item in enumerate(items):
        if pred(item):
            return i
    return -1

tests.unittest_code:
def test_first_index(self):
    self.assertEqual(first_index([1, 3, 5], lambda x: x % 2 == 0), -1)
    self.assertEqual(first_index([1, 4, 5], lambda x: x % 2 == 0), 1)

